mapper.update:
UPDATE sys_user
real_name = #{realName}, phone = #{phone}, email = #{email}, status = #{status}, password_hash = #{passwordHash}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT id, username, real_name, phone, email, status, last_login_time, create_time FROM sys_user WHERE is_deleted = 0
AND (username LIKE CONCAT('%', #{query.keyword}, '%') OR real_name LIKE CONCAT('%', #{query.keyword}, '%') OR phone LIKE CONCAT('%', #{query.keyword}, '%'))
AND status = #{query.status}
AND id IN (SELECT user_id FROM sys_user_role WHERE role_id = (SELECT id FROM sys_role WHERE role_code = #{query.roleCode}))
ORDER BY create_time DESC LIMIT #{query.pageSize} OFFSET #{query.offset}

SELECT r.role_code FROM sys_role r
INNER JOIN sys_user_role ur ON r.id = ur.role_id
WHERE ur.user_id = #{userId}
